input.oldString:
const draw = () => {
  // Clear
  ctx.fillStyle = '#000';
  ctx.fillRect(0, 0, width, height);

  // Draw particles (glowing)
  ctx.fillStyle = '#0ff';
  for (const p of particles) {
    ctx.beginPath();
    ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2);
    ctx.fill();
  }

  // Draw asteroids
  ctx.fillStyle = '#888';
  for (const a of asteroids) {
    ctx.beginPath();
    ctx.arc(a.x, a.y, a.radius, 0, Math.PI * 2);
    ctx.fill();
  }

  // Draw ship (triangle)
  ctx.save();
  ctx.translate(ship.x, ship.y);
  ctx.rotate(ship.angle);
  ctx.fillStyle = '#fff';
  ctx.beginPath();
  ctx.moveTo( ship.radius, 0);
  ctx.lineTo(-ship.radius, ship.radius / 2);
  ctx.lineTo(-ship.radius, -ship.radius / 2);
  ctx.closePath();
  ctx.fill();
  ctx.restore();

  // UI
  ctx.fillStyle = '#fff';
  ctx.font = '16px sans-serif';
  ctx.fillText('Score: ' + score, 10, 20);
  if (gameOver) {
    ctx.fillStyle = 'red';
    ctx.font = '48px sans-serif';
    ctx.fillText('Game Over', width / 2 - 120, height / 2);
  }
};

input.newString:
const draw = () => {
  // Background gradient (deep space)
  const bgGrad = ctx.createLinearGradient(0, 0, 0, height);
  bgGrad.addColorStop(0, '#001');
  bgGrad.addColorStop(1, '#000');
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  // Starfield (twinkling)
  ctx.fillStyle = '#fff';
  for (const s of stars) {
    // slight flicker via random alpha each frame
    ctx.globalAlpha = 0.6 + Math.random() * 0.4;
    ctx.beginPath();
    ctx.arc(s.x, s.y, s.radius, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.globalAlpha = 1.0; // reset

  // Draw particles (glowing)
  ctx.fillStyle = '#0ff';
  for (const p of particles) {
    ctx.beginPath();
    ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2);
    ctx.fill();
  }

  // Draw asteroids with radial gradient shading
  for (const a of asteroids) {
    const grad = ctx.createRadialGradient(
      a.x, a.y, a.radius * 0.2,
      a.x, a.y, a.radius
    );
    grad.addColorStop(0, '#777');
    grad.addColorStop(1, '#222');
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.arc(a.x, a.y, a.radius, 0, Math.PI * 2);
    ctx.fill();
  }

  // Draw ship with thrust effect
  ctx.save();
  ctx.translate(ship.x, ship.y);
  ctx.rotate(ship.angle);
  // Ship body
  ctx.fillStyle = '#fff';
  ctx.beginPath();
  ctx.moveTo(ship.radius, 0);
  ctx.lineTo(-ship.radius, ship.radius / 2);
  ctx.lineTo(-ship.radius, -ship.radius / 2);
  ctx.closePath();
  ctx.fill();
  // Thrust flame
  ctx.fillStyle = 'orange';
  ctx.beginPath();
  ctx.moveTo(-ship.radius, 0);
  ctx.lineTo(-ship.radius - 6, -4);
  ctx.lineTo(-ship.radius - 6, 4);
  ctx.closePath();
  ctx.fill();
  ctx.restore();

  // UI overlay
  ctx.fillStyle = '#fff';
  ctx.font = '16px sans-serif';
  ctx.fillText('Score: ' + score, 10, 20);
  if (gameOver) {
    ctx.fillStyle = 'red';
    ctx.font = '48px sans-serif';
    ctx.fillText('Game Over', width / 2 - 120, height / 2);
  }
};

